"""Read-only compare optimization run with fixed accepted700 checkpoint."""
import argparse,json,re,collections,bisect
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('case');p.add_argument('--prefix',default='cost_buffers700');a=p.parse_args();root=Path(__file__).resolve().parents[1];out=root/'outputs/consistency_validation_20261015';cases=['coverage_lifecycle_700_r1_20261016',a.case];result=[]
for name in cases:
 trial=root/'outputs'/name;cap=[json.loads(l)for l in(trial/'capture_trace.jsonl').open()];t0=cap[0]['capture_wall_s'];stamps=np.array([f['capture_wall_s']-t0 for f in cap]);pos=np.array([f['position']for f in cap]);step=np.linalg.norm(np.diff(pos,axis=0),axis=1);dt=np.diff(stamps);events=json.load(open(trial/'execution_events.json'));x=json.load(open(trial/'search_round_full_audit.json'));covdata=json.load(open(out/(a.prefix+'_timepoints.json')));covrow=next(q for q in covdata if q['case']==name);cov=[row['latest_coverage_sample']for row in covrow['checkpoints']];times=[v[0]for v in cov];rows=[]
 for cp in [300.,503.,float(stamps[-1])]:
  i=bisect.bisect_right(stamps,cp);ci=bisect.bisect_right(times,cp)-1;slow=step[:max(i-1,0)]<.01;edges=np.diff(np.r_[False,slow,False].astype(int));pauses=[stamps[e]-stamps[b]for b,e in zip(np.flatnonzero(edges==1),np.flatnonzero(edges==-1))];rounds=[r for r in x['all_rounds']if r.get('end',{}).get('wall_s',float('inf'))<=t0+cp];compute=[r['compute_s']for r in rounds if 'compute_s'in r];ev=[e for e in events if e['wall_s']<=t0+cp];rows.append({'elapsed_s':cp,'coverage_m3':cov[ci][1]if ci>=0 else None,'coverage_sample_lag_s':cp-times[ci]if ci>=0 else None,'path_m':float(step[:max(i-1,0)].sum()),'translation_s':float(dt[:max(i-1,0)][step[:max(i-1,0)]>=.01].sum()),'longest_small_step_s':float(max(pauses,default=0)),'blocked_frames':sum(f.get('preview_motion_blocked',False)for f in cap[:i]),'planning_rounds':len(rounds),'planning_total_s':sum(compute),'planning_p95_s':float(np.percentile(compute,95))if compute else None,'stops':dict(collections.Counter(e['reason']for e in ev if e['event']=='emergency_stop'))})
 text=re.sub(r'\x1b\[[0-9;]*m','',(trial/'run.log').read_text(errors='replace'));matrix=[float(v)for v in re.findall(r'Hgrid cost matrix 2 time: ([\d.]+) ms',text)];result.append({'case':name,'checkpoints':rows,'hgrid_matrix_logged_samples':len(matrix),'hgrid_matrix_total_s':sum(matrix)/1000,'hgrid_matrix_median_ms':float(np.median(matrix))if matrix else None,'hgrid_matrix_p95_ms':float(np.percentile(matrix,95))if matrix else None,'final_floor_volumes':json.load(open(trial/'floor_volumes.json')),'regions':json.load(open(trial/'consistency_audit.json'))['regions'],'handover_checks':x['checks'],'rejects':x['server_rejections']})
(out/(a.prefix+'_comparison.json')).write_text(json.dumps({'runs':result,'limits':['Timing distributions compare different online trajectories/maps, not identical workloads; regression microbenchmark is separate.','Actual captured wall-clock time, not an independent physics clock.','Different routes can change coverage without changing selection semantics.']},indent=2));print(json.dumps(result,indent=2))
